written=[]
for cid in IDS:
    d=P[cid]
    rec={"case_id":cid,"prediction_text":d["prediction_text"],"basis":d["basis"],"confidence":d["confidence"],"trigger":d["trigger"]}
    with open(os.path.join(OUT,cid+".json"),"w",encoding="utf-8") as f:
        json.dump(rec,f,ensure_ascii=False,indent=1)
    written.append(cid)
assert len(written)==20, len(written)
assert set(written)==set(IDS)
for cid in IDS:
    r=json.load(open(os.path.join(OUT,cid+".json"),encoding="utf-8"))
    assert r["case_id"]==cid
    for k in ["prediction_text","basis","confidence","trigger"]:
        assert k in r and r[k] not in (None,"")
    for k in ["changed_main","reserve_used","disputed","reason"]:
        assert k in r["trigger"]
    assert isinstance(r["confidence"],(int,float)) and 0<=r["confidence"]<=1
cm=sum(1 for c in IDS if P[c]["trigger"]["changed_main"]); ru=sum(1 for c in IDS if P[c]["trigger"]["reserve_used"]); di=sum(1 for c in IDS if P[c]["trigger"]["disputed"])
